-- 1.1  NEW  curated_set_questions   (2026_11_07_100000) - questions staff/seeder add to a Vault AI Interview set
CREATE TABLE IF NOT EXISTS curated_set_questions (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  set_id VARCHAR(80) NOT NULL,
  stack_key VARCHAR(50) NOT NULL,
  series_number TINYINT UNSIGNED NOT NULL,
  set_number TINYINT UNSIGNED NOT NULL,
  position INT UNSIGNED NOT NULL DEFAULT 0,
  text TEXT NOT NULL,
  category VARCHAR(30) NOT NULL DEFAULT 'technical',
  duration_seconds SMALLINT UNSIGNED NOT NULL DEFAULT 180,
  note TEXT NULL,
  created_by BIGINT UNSIGNED NULL,
  created_at TIMESTAMP NULL DEFAULT NULL,
  updated_at TIMESTAMP NULL DEFAULT NULL,
  PRIMARY KEY (id),
  KEY curated_set_questions_set_id_index (set_id),
  KEY curated_set_questions_stack_key_index (stack_key),
  KEY curated_set_questions_set_id_position_index (set_id, position),
  CONSTRAINT curated_set_questions_created_by_foreign FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 1.2  NEW  vault_stack_interests   (2026_11_07_100000) - "Notify me" taps on stacks that are not open yet
CREATE TABLE IF NOT EXISTS vault_stack_interests (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  user_id BIGINT UNSIGNED NOT NULL,
  stack_key VARCHAR(50) NOT NULL,
  notified_at TIMESTAMP NULL DEFAULT NULL,
  created_at TIMESTAMP NULL DEFAULT NULL,
  updated_at TIMESTAMP NULL DEFAULT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uniq_user_stack_interest (user_id, stack_key),
  KEY vault_stack_interests_stack_key_index (stack_key),
  CONSTRAINT vault_stack_interests_user_id_foreign FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 1.3  NEW  readiness_overrides   (2026_11_08_100000) - a readiness score a superadmin set by hand for one student
CREATE TABLE IF NOT EXISTS readiness_overrides (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  user_id BIGINT UNSIGNED NOT NULL,
  score TINYINT UNSIGNED NOT NULL,
  reason VARCHAR(300) NOT NULL,
  set_by_id BIGINT UNSIGNED NULL,
  expires_at TIMESTAMP NULL DEFAULT NULL,
  created_at TIMESTAMP NULL DEFAULT NULL,
  updated_at TIMESTAMP NULL DEFAULT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY readiness_overrides_user_id_unique (user_id),
  KEY readiness_overrides_expires_at_index (expires_at),
  CONSTRAINT readiness_overrides_user_id_foreign FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT readiness_overrides_set_by_id_foreign FOREIGN KEY (set_by_id) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 1.4  NEW  mock_interview_questions   (2026_11_09_100000; topic / needs_review / origin / image columns are folded in here, see 1.9-1.12)
CREATE TABLE IF NOT EXISTS mock_interview_questions (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  stack_key VARCHAR(60) NOT NULL,
  round_number TINYINT UNSIGNED NOT NULL,
  position SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  text TEXT NOT NULL,
  category VARCHAR(20) NOT NULL DEFAULT 'technical',
  duration_seconds SMALLINT UNSIGNED NOT NULL DEFAULT 180,
  note TEXT NULL,
  created_by BIGINT UNSIGNED NULL,
  created_at TIMESTAMP NULL DEFAULT NULL,
  updated_at TIMESTAMP NULL DEFAULT NULL,
  PRIMARY KEY (id),
  KEY mock_interview_questions_stack_key_index (stack_key),
  KEY mock_questions_round_order (stack_key, round_number, position),
  CONSTRAINT mock_interview_questions_created_by_foreign FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 1.5  NEW  platform_modules   (2026_11_15_100000) - superadmin on/off switches (Merchant Navy)
CREATE TABLE IF NOT EXISTS platform_modules (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `key` VARCHAR(64) NOT NULL,
  enabled TINYINT(1) NOT NULL DEFAULT 1,
  updated_by BIGINT UNSIGNED NULL,
  created_at TIMESTAMP NULL DEFAULT NULL,
  updated_at TIMESTAMP NULL DEFAULT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY platform_modules_key_unique (`key`),
  CONSTRAINT platform_modules_updated_by_foreign FOREIGN KEY (updated_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 1.6  NEW  study_attempts   (2026_11_15_100000) - one row per finished Merchant Navy study sitting (score history + reports)
CREATE TABLE IF NOT EXISTS study_attempts (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  user_id BIGINT UNSIGNED NOT NULL,
  interview_id BIGINT UNSIGNED NULL,
  stack_key VARCHAR(64) NOT NULL,
  exam_name VARCHAR(120) NOT NULL,
  round_id VARCHAR(120) NOT NULL,
  set_number SMALLINT UNSIGNED NOT NULL,
  set_title VARCHAR(60) NOT NULL,
  score TINYINT UNSIGNED NOT NULL,
  question_count SMALLINT UNSIGNED NOT NULL,
  answered_count SMALLINT UNSIGNED NOT NULL,
  green_count SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  yellow_count SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  red_count SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  duration_seconds INT UNSIGNED NULL,
  completed_at DATETIME NOT NULL,
  results JSON NOT NULL,
  created_at TIMESTAMP NULL DEFAULT NULL,
  updated_at TIMESTAMP NULL DEFAULT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY study_attempts_sitting_unique (interview_id, completed_at),
  KEY study_attempts_history_index (user_id, stack_key, set_number, completed_at),
  CONSTRAINT study_attempts_user_id_foreign FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

