-- =====================================================================================================================
-- PART 5 - RECORD THE MIGRATIONS (so `php artisan migrate` on the server will not run them a second time and fail with "already exists")
-- =====================================================================================================================
SELECT m.name, (SELECT COALESCE(MAX(b.batch), 0) + 1 FROM (SELECT batch FROM migrations) b)
  FROM (
    SELECT '2026_11_07_100000_create_curated_set_questions_and_stack_interests' AS name UNION ALL
    SELECT '2026_11_08_100000_create_readiness_overrides_table' UNION ALL
    SELECT '2026_11_08_100100_add_admin_fields_to_vault_interview_qualifications' UNION ALL
