-- PART 6 - VERIFY (read-only). Expected on a first run:
--   curated_set_questions = 1305   mock_interview_questions = 2136   platform_modules.merchant_navy = 1   missing_migrations = 0
-- =====================================================================================================================
SELECT (SELECT COUNT(*) FROM curated_set_questions)                         AS curated_set_questions_expect_1305,
       (SELECT COUNT(DISTINCT stack_key) FROM curated_set_questions)        AS curated_stacks,
       (SELECT COUNT(*) FROM mock_interview_questions)                      AS mock_interview_questions_expect_2136,
       (SELECT COUNT(DISTINCT stack_key) FROM mock_interview_questions)     AS mock_stacks,
       (SELECT enabled FROM platform_modules WHERE `key` = 'merchant_navy') AS merchant_navy_enabled,
       (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema = DATABASE()
          AND table_name IN ('curated_set_questions','vault_stack_interests','readiness_overrides','mock_interview_questions','platform_modules','study_attempts')) AS new_tables_expect_6,
       (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND (
            (table_name = 'vault_interview_qualifications' AND column_name IN ('admin_log','attempt_offset','cycle_start','qualified_by_admin_id'))
         OR (table_name = 'password_reset_otps' AND column_name = 'code_encrypted')
         OR (table_name = 'interview_question_banks' AND column_name IN ('reference_unverified','image'))
         OR (table_name = 'interview_responses' AND column_name = 'match_details'))) AS new_columns_expect_8,
       (SELECT COUNT(*) FROM migrations WHERE migration LIKE '2026_11_%' AND migration >= '2026_11_07') AS migrations_recorded;
